const script = `export default async (ctx, client) => {
  const summarize = (value) => {
    if (Array.isArray(value)) return { kind: 'array', length: value.length };
    if (value && typeof value === 'object') {
      const out = { kind: 'object', keys: Object.keys(value).slice(0, 20) };
      for (const key of ['agents','profiles','behaviors','items','classifiers','connections','conversations','entities','types','feeds','results','entity_types','notifications','operations','schedules']) {
        if (Array.isArray(value[key])) out[key + '_count'] = value[key].length;
      }
      return out;
    }
    return { kind: typeof value, value };
  };
  const results = {};
  const check = async (name, fn) => {
    try { results[name] = { ok: true, value: summarize(await fn()) }; }
    catch (error) { results[name] = { ok: false, error: error instanceof Error ? error.message : String(error) }; }
  };
  let agentId = null;
  try {
    const listed = await client.agents.list();
    agentId = listed?.agents?.[0]?.id ?? null;
    results['agents.list'] = { ok: true, value: summarize(listed) };
  } catch (error) {
    results['agents.list'] = { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
  await check('authProfiles.list', () => client.authProfiles.list());
  await check('behaviors.list', () => client.behaviors.list({}));
  await check('catalog.listInstalled', () => client.catalog.listInstalled({ kinds: ['connectors'] }));
  await check('classifiers.list', () => client.classifiers.list());
  await check('connections.list', () => client.connections.list({ limit: 1 }));
  if (agentId) await check('conversations.list', () => client.conversations.list({ agent_id: agentId, limit: 1 }));
  else results['conversations.list'] = { ok: false, error: 'no readable agent available' };
  await check('entities.list', () => client.entities.list({ limit: 1 }));
  await check('entitySchema.listTypes', () => client.entitySchema.listTypes({ list_scope: 'organization' }));
  await check('feeds.list', () => client.feeds.list({ limit: 1 }));
  await check('knowledge.search', () => client.knowledge.search({ query: 'zzqxmcpcheck', limit: 1 }));
  await check('metrics.list', () => client.metrics.list());
  await check('notifications.list', () => client.notifications.list({ limit: 1 }));
  await check('operations.listAvailable', () => client.operations.listAvailable({ query: 'browser' }));
  await check('organizations.list', () => client.organizations.list());
  await check('schedules.list', () => client.schedules.list({ limit: 1 }));
  await check('viewTemplates.get', () => client.viewTemplates.get({ resource_type: 'entity_type', resource_id: 'company' }));
  await check('ctx.sleep', async () => { await ctx.sleep(10); return { slept: true }; });
  return results;
}`;
